    /// 解析一次缓存住：这些路径有几百个点，每帧重解太亏。
    private static var cache: [String: Path] = [:]

    static func path(_ commands: String) -> Path {
        if let hit = cache[commands] { return hit }
        let p = parse(commands)
        cache[commands] = p
        return p
    }

    private static func parse(_ commands: String) -> Path {
        var path = Path()
        let t = commands.split(separator: " ")
        func n(_ i: Int) -> CGFloat { CGFloat(Double(t[i]) ?? 0) }
        var i = 0
        while i < t.count {
            switch t[i] {
            case "M":
                guard i + 2 < t.count else { return path }
                path.move(to: CGPoint(x: n(i + 1), y: n(i + 2))); i += 3
            case "L":
                guard i + 2 < t.count else { return path }
                path.addLine(to: CGPoint(x: n(i + 1), y: n(i + 2))); i += 3
            case "C":
                guard i + 6 < t.count else { return path }
                path.addCurve(to: CGPoint(x: n(i + 5), y: n(i + 6)),
                              control1: CGPoint(x: n(i + 1), y: n(i + 2)),
                              control2: CGPoint(x: n(i + 3), y: n(i + 4)))
                i += 7
            case "Z":
                path.closeSubpath(); i += 1
            default:
                i += 1
            }
        }
        return path
    }
}

/// 把 24×24 的 mark 铺到给定 rect（等比，居中）。
struct MarkShape: Shape {
    let commands: String
    func path(in rect: CGRect) -> Path {
        let s = min(rect.width, rect.height) / 24
        let tx = rect.minX + (rect.width - 24 * s) / 2
        let ty = rect.minY + (rect.height - 24 * s) / 2
        return AgentMark.path(commands)
            .applying(CGAffineTransform(scaleX: s, y: s).concatenating(
                CGAffineTransform(translationX: tx, y: ty)))
    }
}

extension AgentKind {
    /// 品牌色（实心底）
    var brand: Color {
        switch self {
        case .claude: return Color(hex: 0xD97757)
        case .codex: return Color(hex: 0xFFFFFF)
        case .deepseek: return Color(hex: 0x4D6BFE)
        }
    }
    /// 压在品牌色上的图形色
    var ink: Color {
        switch self {
        case .claude: return .white
        case .codex: return Color(hex: 0x0B0C0E)
        case .deepseek: return .white
        }
    }
    var markCommands: String {
        switch self {
        case .claude: return AgentMark.claude
        case .codex: return AgentMark.codex
        case .deepseek: return AgentMark.deepseek
        }
    }
}

/// 头像右下角那颗小圆标：品牌色圆盘 + 官方 mark，外面一圈底色描边把它从头像上抠出来。
struct AgentBadge: View {
    let kind: AgentKind
    /// 圆盘直径（描边另占 1.5pt，所以整体比它大 3pt）
    var size: CGFloat = 13
    /// 描边色 = 这颗标识压在什么底上
    var ring: Color = Theme.panel

    var body: some View {
        ZStack {
            Circle().fill(kind.brand)
            MarkShape(commands: kind.markCommands)
                .fill(kind.ink, style: FillStyle(eoFill: true))
                .frame(width: size * 0.62, height: size * 0.62)
        }
        .frame(width: size, height: size)
        .padding(1.5)
        .background(Circle().fill(ring))
    }
}
